INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'blueair'), 'Blue Pure 411', 'blueair-blue-pure-411-replacement-filter', 'air_purifier', 'replacement filter for blueair blue pure 411', NULL, NULL, NULL, NULL, 'Buyers should confirm the exact Blueair Blue Pure 411 model and part number on their unit’s label before purchasing, as listings include filters for 411, 411+, and 411 Auto variants.', '[{"q": "What official part code is required for a Blueair Blue Pure 411 replacement filter?", "a": "The product titles do not list a specific official part code; customers should check the label on their unit for the correct code."}, {"q": "Are OEM (Blueair) filters different from third‑party replacements for the Blue Pure 411?", "a": "OEM filters are labeled as Blueair genuine and are made by the manufacturer, while third‑party filters are compatible replacements without Blueair branding; performance and warranty may differ."}, {"q": "What filtration grade or maintenance schedule applies to these replacement filters?", "a": "No HEPA grade or dimensions are mentioned in the titles; users should follow Blueair’s typical recommendation to replace the filter about every six months or according to usage."}]', 'Replacement filters compatible with the Blueair Blue Pure 411 air purifier are sold under various listings; no specific official part code or HEPA grade is disclosed in the titles. Both Blueair‑genuine (OEM) filters and third‑party multi‑pack replacements are offered, fitting the 411, 411+, and 411 Auto models.', '["Fits Blueair Blue Pure 411, 411+, and 411 Auto air purifiers.", "Listings do not disclose HEPA grade, filter shape, or exact dimensions.", "Both Blueair‑genuine OEM filters and third‑party multi‑pack replacements are sold."]', 'published') ON CONFLI