INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'levoit'), '400S P', 'levoit-400s-p-replacement-filter', 'air_purifier', 'levoit 400s p replacement filter', NULL, 'H13', NULL, NULL, 'Verify your specific unit is the Levoit Core 400S-P or Core 400S-rf variant, as listings indicate compatibility with these specific smart WiFi models. Do not assume cross-compatibility with other Levoit series without checking the model sticker.', '[{"q": "What filter is compatible with the Levoit 400S P?", "a": "The Levoit 400S P uses a 3-in-1 replacement filter that includes a True H13 HEPA layer, activated carbon, and a pre-filter. Listings confirm compatibility with the Core 400S-P and Core 400S-rf models."}, {"q": "Is there a difference between OEM and third-party filters for this model?", "a": "Yes, genuine Levoit filters are available as official replacements, while third-party options offer similar 3-in-1 H13 HEPA filtration. Third-party listings often have higher review counts, but OEM filters are manufactured by Levoit."}, {"q": "What filtration features do these replacement filters have?", "a": "The filters are described as 3-in-1 systems containing a True H13 HEPA filter, activated carbon for odor removal, and a pre-filter. This multi-layer design is standard for the Levoit Core 400S series."}]', 'The Levoit 400S P utilizes a 3-in-1 replacement filter assembly featuring a True H13 HEPA layer, activated carbon, and a pre-filter. While specific official part codes are not explicitly listed in the provided data, genuine Levoit filters and third-party replacements are available. Buyers should verify compatibility with the Core 400S-P variant to ensure proper fit and filtration performance for their smart WiFi air purifier.', '["Compatible with Levoit Core 400S, Core 400S-P, and Core 400S-rf models.", "Filters feature a 3-in-1 design including True H13 HEPA, activated carbon, and pre-filter layers.", "Options include genuine Levoit single packs and third-party replacements with varying review counts."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
