INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'levoit'), 'Core 200S 3 Stage', 'levoit-core-200s-3-stage-replacement-filter', 'air_purifier', 'levoit core 200s 3 stage replacement filter', 'Core 200S-RF', 'H13', NULL, NULL, 'Verify that your device is specifically the Levoit Core 200S or Core 200S-P, as these filters are not compatible with other Levoit Core series models like the Core 300 or Core 400. Check the model sticker on the bottom of your unit to confirm the exact variant before purchasing.', '[{"q": "What is the official part number for the Levoit Core 200S replacement filter?", "a": "The official part number listed for the Levoit Core 200S replacement filter is Core 200S-RF. This code is referenced in both OEM and third-party product listings for the Core 200S and Core 200S-P models."}, {"q": "Are third-party filters for the Levoit Core 200S identical to OEM filters?", "a": "Third-party filters, such as the Cabiclean 2-pack, are marketed as compatible replacements that compare to the Core 200S-RF part number. While they fit the device, they are not manufactured by Levoit, so buyers should review specific brand warranties and filtration certifications."}, {"q": "What filtration grade does the Levoit Core 200S filter use?", "a": "The Levoit Core 200S uses a 3-Stage filtration system featuring H13 Grade True HEPA. This grade is explicitly mentioned in product titles for the Core 200S-RF filter, indicating high-efficiency capture of fine particles."}]', 'The Levoit Core 200S 3 Stage air purifier utilizes the Core 200S-RF replacement filter. Listings confirm this unit features a 3-Stage H13 Grade True HEPA filtration system. Both official Levoit replacements and third-party multi-pack alternatives are available for this specific model, ensuring consistent air quality performance for the Core 200S and Core 200S-P variants.', '["The compatible filter part number is Core 200S-RF, designed specifically for the Levoit Core 200S and Core 200S-P models.", "The filtration system is identified as 3-Stage H13 Grade True HEPA, providing high-efficiency particulate removal.", "Consumers can choose between official Levoit units and third-party 2-pack replacements, with the latter often offering cost-effective bulk options."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'levoit'), 'Core 400S 3 Stage', 'levoit-core-400s-3-stage-replacement-filter', 'air_purifier', 'levoit core 400s 3 stage replacement filter', NULL, 'H13', NULL, NULL, 'Buyers should confirm the exact model designation on their unit’s sticker (e.g., Core 400S‑P or Core400S‑rf) before purchasing, as the listings include filters for several Core 400S variants.', '[{"q": "What part code or model identifier should I look for when buying a replacement filter for the Levoit Core 400S 3‑Stage?", "a": "The filters are identified by the model name “Core 400S” (including Core 400S‑P and Core400S‑rf variants); no separate official part number is listed in the titles."}, {"q": "Is there a difference between OEM Levoit filters and third‑party replacements?", "a": "OEM filters are manufactured by Levoit and sold as single packs, while third‑party options are often sold in multi‑packs and may be compatible but are not branded as Levoit."}, {"q": "What filtration grade do the listed replacement filters provide?", "a": "The titles specify a True H13 HEPA grade combined with an activated carbon pre‑filter, indicating high‑efficiency particulate capture."}]', 'Replacement filters compatible with the Levoit Core 400S 3‑Stage air purifier are identified by the model name “Core 400S” rather than a distinct part number; the listings cite a True H13 HEPA grade. Both OEM Levoit filters and third‑party multi‑pack replacements appear in the market, offering equivalent fit.', '["Filters labeled “Core 400S” fit Levoit Core 400S 3‑Stage units (including Core 400S‑P and Core400S‑rf variants).", "Listings mention a True H13 HEPA grade with activated carbon pre‑filter.", "Both OEM single‑pack Levoit filters and third‑party multi‑pack replacements are sold."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
