INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'coway'), 'Storm 2 Replacement', 'coway-storm-2-replacement-replacement-filter', 'air_purifier', 'coway storm 2 filter replacement', 'AP-1516D', NULL, NULL, NULL, 'Verify your specific Coway Storm 2 Replacement model sticker matches the AP-1516D, AP1516D, AP-1207BH, or APM-1516E designations before ordering. Note that some listed genuine Coway filters are for the Airmega Mighty2 and may not fit the Storm 2 series.', '[{"q": "What is the official filter part number for the Coway Storm 2 Replacement?", "a": "The listings identify AP-1516D as the primary filter code, with compatibility also listed for AP1516D, AP-1207BH, and APM-1516E."}, {"q": "Are there OEM and third-party options available for this filter?", "a": "Yes, third-party replacements are available, including single and dual-filter packs. While genuine Coway filters are listed, the specific genuine options shown are for the Airmega Mighty2, requiring verification for Storm 2 compatibility."}, {"q": "What filtration features are mentioned for the AP-1516D filter?", "a": "The product titles explicitly mention an ''Activated Carbon Deodorizing Filter'' component, but do not specify a HEPA grade or exact dimensions."}]', 'The Coway Storm 2 Replacement utilizes the AP-1516D filter code, which is compatible with models AP-1516D, AP1516D, AP-1207BH, and APM-1516E. Listings indicate this filter includes activated carbon deodorizing capabilities. Both genuine OEM options and third-party replacement packs are available, with some third-party options offering dual-filter configurations for extended maintenance intervals.', '["The primary filter part number identified for the Coway Storm 2 Replacement is AP-1516D, with cross-compatibility noted for AP-1207BH and APM-1516E.", "Filtration features explicitly mentioned in listings include activated carbon deodorizing, though specific HEPA grades are not detailed in the provided titles.", "Buying options include third-party single or dual-filter replacements and genuine Coway filters, though the latter listed are for the Airmega Mighty2, not the Storm 2."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
