INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'winix'), '5300 2 Replacement', 'winix-5300-2-replacement-replacement-filter', 'air_purifier', 'winix 5300 2 hepa filter replacement', '115115', 'HEPA', NULL, NULL, 'Verify the model number and part code on your unit’s filter compartment (e.g., 5300‑2, 115115) before purchasing, as some listings also cover C535, P300, and other Winix variants.', '[{"q": "What part number filter A for the Winix 5300‑2 uses?", "a": "The replacement filter A for the Winix 5300‑2 is identified by part number 115115, as shown in the product titles."}, {"q": "Is there a difference between OEM Winix filters and third‑party replacements?", "a": "OEM filters are labeled as genuine Winix and guarantee exact manufacturer specifications, while third‑party filters are compatible replacements that may offer HEPA rating and multi‑pack value but are not made by Winix."}, {"q": "Do the listed filters include HEPA filtration or additional carbon pre‑filters?", "a": "Some listings specify a HEPA‑rated filter A (115115) and multi‑pack bundles that add carbon pre‑filters, while others do not mention HEPA or carbon features."}]', 'The Winix 5300‑2 air purifier uses filter A, part number 115115. It is available as an OEM genuine Winix filter and as third‑party HEPA‑rated replacements, including multi‑pack options that add carbon pre‑filters. Both types meet the model’s filtration requirements. These filters fit the 5300‑2’s A‑slot and maintain the unit’s advertised air‑cleaning performance.', '["Filter A part 115115 fits Winix 5300‑2 and related models such as C535 and P300.", "Listings include HEPA‑rated options and some bundles add carbon pre‑filters for odor control.", "Both genuine Winix OEM filters and third‑party multi‑pack value sets are available for purchase."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
