INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'winix'), '3 Stage True', 'winix-3-stage-true-replacement-filter', 'air_purifier', 'winix 3 stage air purifier true hepa filter', NULL, NULL, NULL, NULL, 'Verify your exact Winix 3 Stage True model number (e.g., C535) against the product listing, as other Winix models like the 5500-2 and D360 use different filter part numbers and dimensions.', '[{"q": "What is the official filter part number for the Winix 3 Stage True?", "a": "The provided listings do not specify an official OEM part number for the Winix 3 Stage True. However, the FilterTech listing confirms compatibility with the Winix C535 3-Stage True HEPA Air Purifier."}, {"q": "Are there OEM filters available for the Winix 3 Stage True in these listings?", "a": "No, the only OEM filter listed is for the Winix 5500-2 model. The listings for the 3 Stage True (specifically the C535 variant) are from third-party manufacturers like FilterTech."}, {"q": "What filtration features are mentioned for the Winix 3 Stage True replacement filters?", "a": "The listings mention ''3-Stage True HEPA'' filtration for the C535 model. Other Winix filters in the data mention H13 True HEPA and Activated Carbon, but these are for different models (D360)."}]', 'Replacement filters for the Winix 3 Stage True air purifier include third-party options like the FilterTech 1-Year Set for the C535 model. While specific OEM part numbers for this exact model are not listed in the provided data, third-party replacements are available. Buyers should verify their specific unit''s model number to ensure compatibility with the 3-Stage True HEPA filtration system.', '["The FilterTech 1-Year Set is explicitly listed as compatible with the Winix C535 3-Stage True HEPA Air Purifier.", "Listed third-party options include multi-pack sets containing both HEPA and activated carbon filters, though specific part codes for the 3 Stage True model are not provided in the source data.", "OEM Winix filters listed in the data are for different models (5500-2), so buyers must verify if a specific OEM part exists for the 3 Stage True or rely on verified third-party compatibility."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
