INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'honeywell'), '1 Zoll', 'honeywell-1-zoll-replacement-filter', 'air_purifier', 'honeywell filter 1 zoll', 'HRF-APP1', 'HEPA', NULL, NULL, 'Verify your specific Honeywell 1 Zoll model sticker to ensure compatibility, as listings reference distinct series such as HPA100/200/300 and 5000. Confirm whether your unit requires the HRF-APP1 pre-filter or the HRF-R series HEPA filter before ordering.', '[{"q": "What is the official filter part code for the Honeywell 1 Zoll?", "a": "Listings identify HRF-APP1 as the pre-filter code and HRF-R1, HRF-R2, and HRF-R3 as compatible HEPA filter codes for Honeywell air purifiers."}, {"q": "Are there OEM and third-party options available?", "a": "Yes, genuine Honeywell filters are available, such as the HRF-APP1 and HEPA Filter R. Third-party options include Funmit 6-pack replacements compatible with HRF-R series filters."}, {"q": "What filtration features are mentioned in the product listings?", "a": "The listings specify HEPA filtration for the HPA300 and HPA100/200/300/5000 series, as well as A+ pre-filtration for the HRF-APP1 model."}]', 'Replacement filters for the Honeywell 1 Zoll air purifier include the HRF-APP1 pre-filter and HRF-R series HEPA filters. Listings indicate compatibility with HPA100, HPA200, HPA300, and 5000 series models. Both genuine Honeywell OEM units and third-party multi-pack replacements are available, offering options for single-unit or bulk filtration maintenance.', '["Compatible filter codes identified in listings include HRF-APP1 for pre-filtration and HRF-R1, HRF-R2, and HRF-R3 for HEPA filtration.", "Listings specify HEPA filtration capabilities, with options ranging from single OEM packs to third-party 6-pack value sets.", "Buyers can choose between genuine Honeywell manufactured filters and third-party replacements like Funmit, which offer multi-pack configurations."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
