INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'germguardian'), 'C FLT5000', 'germguardian-c-flt5000-replacement-filter', 'air_purifier', 'germguardian replacement filter c flt5000', 'FLT5000', 'True HEPA', NULL, NULL, 'Verify your specific GermGuardian model number against the compatibility list, as the FLT5000 filter fits multiple variants including AC5000E, AC5250PT, and AC5350B. Ensure your device''s part sticker matches these listed models before ordering to avoid fitment issues.', '[{"q": "What is the correct filter part number for the GermGuardian C FLT5000?", "a": "The correct part number is FLT5000. This filter is also compatible with other models such as AC5000E, AC5250PT, AC5350B, and CDAP5500B."}, {"q": "Is the FLT5000 filter available as an OEM or third-party option?", "a": "Yes, the FLT5000 filter is available as a genuine GermGuardian OEM product and as third-party replacements in 2, 3, or 4-pack configurations."}, {"q": "What type of filtration does the FLT5000 filter provide?", "a": "The FLT5000 filter is specified as a True HEPA filter, designed to capture fine particulate matter for improved air quality."}]', 'The GermGuardian C FLT5000 air purifier utilizes the FLT5000 True HEPA replacement filter. This specific part number is compatible with multiple GermGuardian models, including the AC5000E and AC5250PT. Both genuine OEM units and third-party multi-pack replacements are available for purchase, ensuring consistent filtration performance for devices requiring this specific filter configuration.', '["The official replacement filter code is FLT5000, explicitly identified as a True HEPA filter in product listings.", "Compatibility extends to various GermGuardian models such as AC5000, AC5000E, AC5250PT, AC5350B, and CDAP5500B.", "Buyers can choose between single genuine OEM filters or cost-effective third-party multi-packs (2, 3, or 4 units)."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
