INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'germguardian'), '3 In 1', 'germguardian-3-in-1-replacement-filter', 'air_purifier', 'germguardian 3 in 1 hepa filter air purifier', 'FLT4825', 'H13', NULL, NULL, 'Verify the exact model number on your device''s sticker, as the FLT4825 filter is listed for specific variants like AC4825, AC4825E, and AC4825W. Do not assume compatibility with other GermGuardian series such as the AC4100 or AC4150, which use different filter codes like FLT4100.', '[{"q": "What is the official filter part number for the GermGuardian 3 In 1?", "a": "The listings identify FLT4825 as the HEPA replacement filter code for the GermGuardian 3 In 1 and related models like the AC4825."}, {"q": "Is the FLT4825 filter available as an OEM or third-party option?", "a": "Both options are available; there are genuine GermGuardian filters and third-party replacements, including multi-packs that include additional carbon pre-filters."}, {"q": "What filtration grade does the FLT4825 filter provide?", "a": "The FLT4825 filter is specified as an H13 True HEPA filter, designed to capture fine particulate matter."}]', 'The GermGuardian 3 In 1 air purifier utilizes the FLT4825 filter, which is an H13 True HEPA replacement. This filtration system is compatible with various GermGuardian models including the AC4825 series. Buyers can select between genuine OEM filters and third-party multi-pack replacements that include carbon pre-filters for enhanced odor control and extended maintenance intervals.', '["The primary replacement filter code identified for the GermGuardian 3 In 1 is FLT4825, which is an H13 True HEPA filter.", "Compatibility extends to multiple GermGuardian models such as AC4825, AC4825E, AC4825W, AC4300, AC4800, AC4900, and AC4850.", "Purchase options include single genuine OEM filters and third-party value packs containing four H13 HEPA filters plus eight carbon pre-filters."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
INSERT INTO devices (brand_id, model_name, slug, category, seed_keyword, official_filter_code, hepa_grade, filter_shape, dimensions_json, compatibility_warning, faqs_json, direct_answer_capsule, key_takeaways_json, status) VALUES ((SELECT id FROM brands WHERE slug = 'medify'), 'H13 True Replacement', 'medify-h13-true-replacement-replacement-filter', 'air_purifier', 'medify h13 true hepa filter replacement', NULL, 'H13', NULL, NULL, 'Buyers must verify their specific Medify model number, as listings indicate compatibility with variants such as MA-14, MA-14W, and MA-14B, which may differ from the H13 True Replacement. Always check the device''s sticker or manual for the exact part number before ordering to ensure fitment.', '[{"q": "What is the official filter part code for the Medify H13 True Replacement?", "a": "The scraped listings do not explicitly state a single official filter part code for the H13 True Replacement. However, they confirm compatibility with True HEPA H13 filters and reference specific Medify models like MA-14 and MA-25 for genuine replacements."}, {"q": "What is the difference between OEM and third-party filters for this device?", "a": "OEM filters are manufactured by Medify and labeled as ''Genuine'' in listings, such as the MA-25 and MA-40 sets. Third-party filters, like those from LifeSupplyUSA, are labeled as ''True HEPA'' replacements and are often sold in multi-packs, offering a value alternative to the official brand."}, {"q": "What filtration features do these replacement filters offer?", "a": "The filters feature a 3-in-1 design with a pre-filter, HEPA, and activated carbon layer. They are rated for H13 True HEPA filtration and are designed to remove particles down to 0.3 microns, including allergens, smoke, dust, and odors."}]', 'The Medify H13 True Replacement utilizes a True HEPA filtration system, specifically identified as H13 grade in available listings. While no single universal part code is explicitly defined across all scraped data, compatible filters are available as both genuine OEM sets and third-party replacements. These filters typically feature a 3-in-1 design combining pre-filter, HEPA, and activated carbon layers to capture particles down to 0.3 microns.', '["Compatible filters for the Medify H13 True Replacement are available in both genuine OEM and third-party formats, with listings confirming H13 True HEPA filtration capabilities.", "Filtration systems described in the listings are 3-in-1 designs incorporating pre-filter, HEPA, and activated carbon components to remove allergens, smoke, and odors down to 0.3 microns.", "Buying options include single-pack genuine filters and multi-pack third-party replacements, such as 2-packs, allowing consumers to choose between official brand assurance and value-oriented bulk purchasing."]', 'enriched') ON CONFLICT(slug) DO UPDATE SET official_filter_code=excluded.official_filter_code, hepa_grade=excluded.hepa_grade, filter_shape=excluded.filter_shape, dimensions_json=excluded.dimensions_json, compatibility_warning=excluded.compatibility_warning, faqs_json=excluded.faqs_json, direct_answer_capsule=excluded.direct_answer_capsule, key_takeaways_json=excluded.key_takeaways_json, status=excluded.status, updated_at=CURRENT_TIMESTAMP;
